(function(E){ const x = E["exam-05"] = E["exam-05"] || {units:{}}; (x.units = x.units || {})["x05-l4"] = {"id":"x05-l4","patterns":["L4-tech","PARA-signpost"],"title":{"en":"Listening Part 4: a lecture on city streams","tr":"Listening Part 4: şehir dereleri üzerine bir ders","fa":"Listening Part 4: درسی درباره‌ی نهرهای شهری"},"objective":{"en":"In this lesson you will learn to complete ten notes during a lecture with no break: follow the speaker’s signposts from heading to heading, write one word in the form you hear it, and ignore the answer the lecturer corrects.","tr":"Bu derste arasız bir ders sırasında on notu doldurmayı öğreneceksin: konuşanın yol işaretlerini başlıktan başlığa takip edecek, tek kelimeyi duyduğun biçimde yazacak ve öğretim görevlisinin düzelttiği cevabı göz ardı edeceksin.","fa":"در این درس یاد می‌گیری در یک درس بدون وقفه ده یادداشت را کامل کنی: نشانه‌های گوینده را از عنوانی به عنوان دیگر دنبال کنی، یک کلمه را به همان شکلی که می‌شنوی بنویسی و جوابی را که استاد اصلاح می‌کند نادیده بگیری."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 4: a lecture on city streams","tr":"Listening Part 4: şehir dereleri üzerine bir ders","fa":"Listening Part 4: درسی درباره‌ی نهرهای شهری"},"objective":{"en":"In this lesson you will learn to complete ten notes during a lecture with no break: follow the speaker’s signposts from heading to heading, write one word in the form you hear it, and ignore the answer the lecturer corrects.","tr":"Bu derste arasız bir ders sırasında on notu doldurmayı öğreneceksin: konuşanın yol işaretlerini başlıktan başlığa takip edecek, tek kelimeyi duyduğun biçimde yazacak ve öğretim görevlisinin düzelttiği cevabı göz ardı edeceksin.","fa":"در این درس یاد می‌گیری در یک درس بدون وقفه ده یادداشت را کامل کنی: نشانه‌های گوینده را از عنوانی به عنوان دیگر دنبال کنی، یک کلمه را به همان شکلی که می‌شنوی بنویسی و جوابی را که استاد اصلاح می‌کند نادیده بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"1"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word","tr":"1 kelime","fa":"۱ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: daylighting buried streams","tr":"Bu sınav: gömülü dereleri gün ışığına çıkarmak","fa":"این آزمون: بیرون آوردن نهرهای مدفون"},"intro":{"en":"Part 4 is always a talk or lecture on an academic subject. Here it is about cities and engineering. Technology and the built environment come up less often than nature or history, but the lecture always follows the same plan: background, problem, solution, results.","tr":"Part 4 her zaman akademik bir konuda bir konuşma ya da derstir. Burada konu şehirler ve mühendislik. Teknoloji ve yapılı çevre, doğa ya da tarihten daha az çıkar ama ders hep aynı planı izler: arka plan, sorun, çözüm, sonuçlar.","fa":"Part 4 همیشه یک سخنرانی یا درس درباره‌ی یک موضوع علمی است. این‌جا درباره‌ی شهر و مهندسی است. فناوری و محیط ساخته‌شده کمتر از طبیعت یا تاریخ می‌آید، اما درس همیشه همان نقشه را دارد: پیشینه، مشکل، راه‌حل، نتیجه‌ها."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x05-l4-ctx","exam":true,"patterns":["L4-tech","PARA-signpost"],"often":{"pattern":"L4-tech","n":3,"of":40,"label":{"en":"Comes up often in the real exam: 3 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 3’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۳ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A lecture on rivers hidden under a city","tr":"Bir şehrin altına gizlenmiş nehirler üzerine bir ders","fa":"درسی درباره‌ی رودهایی که زیر شهر پنهان شده‌اند"},"asks":{"en":"A lecturer explains a change in how cities are built: why something was done in the past, the problems it causes now, how engineers are reversing it, the benefits and the challenges. The notes follow these headings.","tr":"Bir öğretim görevlisi şehirlerin kuruluş biçimindeki bir değişikliği anlatıyor: geçmişte bir şeyin neden yapıldığını, bugün yol açtığı sorunları, mühendislerin onu nasıl geri çevirdiğini, faydaları ve zorlukları. Notlar bu başlıkları izler.","fa":"یک استاد تغییری را در شیوه‌ی ساختن شهرها توضیح می‌دهد: چرا کاری در گذشته انجام شد، امروز چه مشکلی می‌سازد، مهندس‌ها چطور برش می‌گردانند، فایده‌ها و چالش‌ها. یادداشت‌ها همین عنوان‌ها را دنبال می‌کنند."},"fields":["History","Problems","The process","Benefits","Challenges"],"words":[{"a":"buried","b":"put under the ground / covered over","tr":"gömülü","fa":"زیر خاک رفته، دفن‌شده"},{"a":"to make space for","b":"to make room for / the land was needed for","tr":"... için yer açmak","fa":"جا باز کردن برای"},{"a":"heavy rain","b":"a storm / a downpour","tr":"şiddetli yağmur","fa":"باران شدید"},{"a":"expensive to repair","b":"costly to maintain","tr":"onarımı pahalı","fa":"تعمیرش گران"},{"a":"channel","b":"the path the water runs in","tr":"kanal, yatak","fa":"مسیر آب، آبراه"},{"a":"lined with","b":"the bottom and sides are covered with","tr":"... ile kaplı","fa":"با ... پوشیده"},{"a":"cooler","b":"several degrees lower / less hot","tr":"daha serin","fa":"خنک‌تر"},{"a":"wildlife returns","b":"fish and birds come back","tr":"yaban hayatı geri döner","fa":"حیات وحش برمی‌گردد"},{"a":"opposition","b":"people who are against it / object","tr":"muhalefet, karşı çıkanlar","fa":"مخالفت"},{"a":"first of all","b":"let’s begin with","tr":"ilk olarak","fa":"اول از همه"},{"a":"another point","b":"there’s also / finally, let’s turn to","tr":"bir başka nokta","fa":"نکته‌ی دیگر"},{"a":"to sum up","b":"so, in short","tr":"özetle","fa":"به‌طور خلاصه"}],"traps":[{"en":"\"You might expect... In fact...\" The lecturer names the obvious answer first and then corrects it. Write the word after in fact.","tr":"\"... beklersiniz. Aslında...\" Öğretim görevlisi önce akla gelen cevabı söyler, sonra düzeltir. In fact’ten sonraki kelimeyi yaz.","fa":"«شاید انتظار داشته باشی... در واقع...». استاد اول جواب بدیهی را می‌گوید و بعد اصلاحش می‌کند. کلمه‌ی بعد از in fact را بنویس."},{"en":"Plural and spelling: if you hear an s, write it. \"tunnels\", not \"tunnel\".","tr":"Çoğul ve yazım: s duyuyorsan yaz. \"tunnel\" değil, \"tunnels\".","fa":"جمع و املا: اگر s می‌شنوی بنویسش. «tunnels»، نه «tunnel»."},{"en":"ONE WORD ONLY: \"local shop owners\" is three words. Find the one word that fits the gap.","tr":"ONE WORD ONLY: \"local shop owners\" üç kelime. Boşluğa uyan tek kelimeyi bul.","fa":"ONE WORD ONLY: «local shop owners» سه کلمه است. تک کلمه‌ای را پیدا کن که در جای خالی جا می‌شود."}],"example":{"lines":[["Lecturer","You might think the canals were built for passengers. In fact, almost all the traffic was coal."]],"item":"Canals · mainly used to carry ___","answer":"coal","why":{"en":"Passengers is the expected answer; \"in fact\" gives the right one: coal.","tr":"Yolcular beklenen cevap; \"in fact\" doğrusunu veriyor: kömür.","fa":"مسافرها جواب قابل انتظارند؛ «in fact» جواب درست را می‌دهد: زغال‌سنگ."}}},{"id":"L4-tech","ctx":["L4-tech","L4-society"],"title":{"en":"Technology, energy and cities","tr":"Teknoloji, enerji ve şehirler","fa":"فناوری، انرژی و شهرها"},"asks":{"en":"A lecturer explains how a technology or a part of a city works: rivers in cities, satellites, energy from the sea. The notes cover the problem, how the solution works, its advantages and its drawbacks.","tr":"Bir öğretim görevlisi bir teknolojinin ya da şehrin bir parçasının nasıl çalıştığını anlatır: şehirlerdeki nehirler, uydular, denizden enerji. Notlar sorunu, çözümün nasıl işlediğini, avantajlarını ve dezavantajlarını kapsar.","fa":"یک سخنران توضیح می‌دهد یک فناوری یا بخشی از شهر چطور کار می‌کند: رودخانه‌های شهری، ماهواره‌ها، انرژی از دریا. یادداشت‌ها مسئله، طرز کار راه‌حل، مزیت‌ها و عیب‌هایش را پوشش می‌دهند."},"fields":["The problem","How it works","Equipment","Advantages","Disadvantages","Future developments"],"words":[{"a":"infrastructure","b":"roads, bridges and pipes","tr":"altyapı","fa":"زیرساخت"},{"a":"renewable","b":"it won't run out","tr":"yenilenebilir","fa":"تجدیدپذیر"},{"a":"generate","b":"produce electricity","tr":"üretmek","fa":"تولید کردن"},{"a":"turbine","b":"a machine turned by water or wind","tr":"türbin","fa":"توربین"},{"a":"satellite","b":"a machine that goes round the Earth","tr":"uydu","fa":"ماهواره"},{"a":"debris","b":"broken pieces left in space","tr":"enkaz parçaları","fa":"قطعات و زباله‌ها"},{"a":"sensor","b":"a device that detects something","tr":"sensör","fa":"حسگر"},{"a":"flood","b":"water covering the land","tr":"sel","fa":"سیل"},{"a":"install","b":"put in place","tr":"kurmak","fa":"نصب کردن"},{"a":"running costs","b":"what it costs every year","tr":"işletme maliyeti","fa":"هزینه‌ی نگهداری"},{"a":"durable","b":"lasts a long time","tr":"dayanıklı","fa":"بادوام"},{"a":"prototype","b":"the first test version","tr":"prototip","fa":"نمونه‌ی اولیه"}],"traps":[{"en":"Advantage or drawback: \"it’s cheap to run, although it’s expensive to build\". The heading tells you which one.","tr":"Avantaj mı dezavantaj mı: \"işletmesi ucuz ama kurması pahalı\". Hangisi olduğunu başlık söyler.","fa":"مزیت یا عیب: «نگهداری‌اش ارزان است، هرچند ساختنش گران است». عنوان می‌گوید کدام را بخواهی."},{"en":"Technical words are often explained in simpler words. The gap usually needs the word the speaker actually says.","tr":"Teknik kelimeler çoğu zaman daha basit kelimelerle açıklanır. Boşluk genelde konuşmacının gerçekten söylediği kelimeyi ister.","fa":"کلمه‌های فنی اغلب با کلمه‌های ساده‌تر توضیح داده می‌شوند. جای خالی معمولاً همان کلمه‌ای را می‌خواهد که گوینده واقعاً می‌گوید."}],"example":{"lines":[["Lecturer","Tidal turbines are expensive to install."],["Lecturer","Once they’re in place, though, they’re cheap to run."],["Lecturer","And unlike the wind, the tides are completely predictable."]],"item":"Advantage: the tides are ___   (ONE WORD ONLY)","answer":"predictable","why":{"en":"Cost is a drawback. The advantage over wind: the tides are \"completely predictable\".","tr":"Maliyet bir dezavantaj. Rüzgâra göre avantaj: gelgitler \"tamamen öngörülebilir\".","fa":"هزینه عیب است. مزیت در برابر باد: جزر و مد «کاملاً قابل پیش‌بینی» است."}},"general":true,"patterns":["L4-tech","L4-society"],"often":{"pattern":"L4-tech","n":3,"of":40,"label":{"en":"Comes up often in the real exam: 3 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 3’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۳ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Ten notes, no break","tr":"On not, ara yok","fa":"ده یادداشت، بدون وقفه"},"body":{"en":"Questions 31-40 are notes under five headings. You get 45 seconds to read them all, and the lecture then runs to the end without a pause. Limit: ONE WORD ONLY. The answers come in order, usually one or two per paragraph of the talk.","tr":"Soru 31-40 beş başlık altındaki notlardır. Hepsini okumak için 45 saniyen var, sonra ders duraklamadan sonuna kadar sürer. Sınır: ONE WORD ONLY. Cevaplar sırayla gelir, genelde konuşmanın her paragrafında bir ya da iki tane.","fa":"سؤال‌های ۳۱ تا ۴۰ یادداشت‌هایی زیر پنج عنوان‌اند. ۴۵ ثانیه وقت داری همه را بخوانی و بعد درس بدون مکث تا آخر ادامه پیدا می‌کند. سقف: ONE WORD ONLY. جواب‌ها به ترتیب می‌آیند، معمولاً در هر پاراگراف صحبت یکی دو تا."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Use the signposts","tr":"Yol işaretlerini kullan","fa":"از نشانه‌ها استفاده کن"},"steps":[{"en":"In the 45 seconds, read every heading and guess the kind of word for each gap.","tr":"45 saniyede her başlığı oku ve her boşluk için kelimenin türünü tahmin et.","fa":"در آن ۴۵ ثانیه همه‌ی عنوان‌ها را بخوان و نوع کلمه‌ی هر جای خالی را حدس بزن."},{"en":"Listen for signposts: let’s begin with, so what’s the problem, now the benefits, finally. Each one moves you to the next heading.","tr":"Yol işaretlerini dinle: let’s begin with, so what’s the problem, now the benefits, finally. Her biri seni bir sonraki başlığa geçirir.","fa":"به نشانه‌ها گوش بده: let’s begin with، so what’s the problem، now the benefits، finally. هر کدام تو را به عنوان بعدی می‌برد."},{"en":"Write the word exactly as you hear it, with its plural s, and keep going if you miss one.","tr":"Kelimeyi duyduğun gibi, çoğul s’siyle yaz; birini kaçırırsan devam et.","fa":"کلمه را دقیقاً همان‌طور که می‌شنوی با s جمعش بنویس و اگر یکی را از دست دادی، ادامه بده."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"The corrected guess","tr":"Düzeltilen tahmin","fa":"حدسِ اصلاح‌شده"},"body":{"en":"Lecturers like to name what you might expect and then correct it: \"You might expect concrete... in fact...\" Both words fit the gap grammatically, so the signal words decide. The word after in fact or actually is the answer.","tr":"Öğretim görevlileri beklenebilecek şeyi söyleyip sonra düzeltmeyi sever: \"Beton bekleyebilirsiniz... aslında...\" İki kelime de boşluğa dil bilgisi olarak uyar, bu yüzden işaret kelimeleri karar verir. In fact ya da actually’den sonraki kelime cevaptır.","fa":"استادها دوست دارند اول چیزی را که انتظارش را داری بگویند و بعد اصلاحش کنند: «شاید انتظار بتن داشته باشی... در واقع...». هر دو کلمه از نظر دستوری در جای خالی جا می‌شوند، پس کلمه‌های نشانه تصمیم می‌گیرند. کلمه‌ی بعد از in fact یا actually جواب است."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One note, step by step","tr":"Bir not, adım adım","fa":"یک یادداشت، قدم به قدم"},"instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","item":"Green roofs · Benefits: they reduce the amount of ___ in summer","lines":[["Lecturer","Now, the benefits. People tend to think of wildlife first, but the biggest gain for the building is that a green roof cuts the amount of energy used for air conditioning in summer."]],"answer":"energy","walk":[{"en":"\"Now, the benefits\" tells you that you have reached the Benefits heading.","tr":"\"Now, the benefits\" Benefits başlığına geldiğini söylüyor.","fa":"«Now, the benefits» می‌گوید به عنوان Benefits رسیده‌ای."},{"en":"Wildlife is mentioned first, but \"the biggest gain\" introduces the answer.","tr":"Önce yaban hayatından söz ediliyor ama \"en büyük kazanç\" cevabı getiriyor.","fa":"اول از حیات وحش حرف زده می‌شود، اما «بزرگ‌ترین فایده» جواب را می‌آورد."},{"en":"\"Cuts the amount of energy\" = reduces the amount of energy. One word: energy.","tr":"\"Cuts the amount of energy\" = enerji miktarını azaltır. Tek kelime: energy.","fa":"«cuts the amount of energy» یعنی مقدار انرژی را کم می‌کند. یک کلمه: energy."}]},"quick":{"prompt":"Note: \"Bridges were built from ___ (ONE WORD ONLY)\". You hear: \"You’d expect stone, but in fact most of them were made of iron.\" What do you write?","options":["stone","iron","iron and stone"],"correct":1,"why":{"en":"Stone is what you would expect; \"in fact\" gives the answer, iron.","tr":"Taş beklenen şey; \"in fact\" cevabı veriyor: iron.","fa":"سنگ چیزی است که انتظارش را داری؛ «in fact» جواب را می‌دهد: iron."}},"remember":{"en":"Read all five headings first, let the signposts move you on, and write the one word that comes after in fact.","tr":"Önce beş başlığın hepsini oku, yol işaretleri seni ilerletsin ve in fact’ten sonra gelen tek kelimeyi yaz.","fa":"اول هر پنج عنوان را بخوان، بگذار نشانه‌ها جلو ببرندت و تک کلمه‌ای را بنویس که بعد از in fact می‌آید."},"type":"explain","id":"c-x05-l4-e","course":"ielts-exams","exam":"exam-05","unit":"x05-l4"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 4","title":{"en":"Bringing buried streams back to light","tr":"Gömülü dereleri yeniden gün ışığına çıkarmak","fa":"بیرون آوردن دوباره‌ی نهرهای مدفون"},"timed":8,"ctx":["L4-tech"],"script":[{"who":"Lecturer","line":"Good afternoon. In today's lecture I'm going to talk about something that most city dwellers walk over every day without knowing it: buried streams. I'll explain why so many small rivers disappeared under our cities, what problems that has caused, and how some cities are now bringing them back to the surface, a process known as daylighting."},{"who":"Lecturer","line":"Let's begin with some history. Before the industrial age, most towns grew up along small streams, which supplied water and power for mills. As towns turned into crowded cities in the nineteenth century, those streams changed their role. They were used to carry waste away from houses and factories, and before long they smelled so bad that people demanded they be covered. Engineers built brick tunnels over them, and the land on top was soon needed for something else, mainly to make room for new roads and railways. Within a few decades, hundreds of streams had simply vanished from the map."},{"who":"Lecturer","line":"So what's the problem with leaving them underground? Well, there are two main ones. The first is water. A stream in a pipe can only carry a fixed amount, and when there's very heavy rain, which is becoming more common, the pipe fills up and the water has nowhere to go. The result is flooding, often in streets far from where anyone remembers a river ever was. The second problem is money. Many of those brick tunnels are now well over a century old, and repairing them is extremely expensive. And because the tunnels are hidden, faults are often found only after something has already gone wrong. Some cities spend more each year maintaining a buried stream than it would cost to open it up."},{"who":"Lecturer","line":"That brings me to daylighting itself. What does it actually involve? The first step is finding the stream, which is harder than it sounds. Engineers usually begin with a survey using old maps, because modern plans often don't show buried streams at all. Once the route is known, the tunnel is removed section by section, and a new open channel is built. You might expect that channel to be made of concrete, which is cheap and strong. In fact, designers now prefer to line it with gravel and plant the banks, so that the stream behaves more like a natural one. The whole process is slow. Even a short stretch of a few hundred metres can take three or four years from the first survey to the day the water runs in the open, mostly because every pipe and cable that crosses the old tunnel has to be moved first."},{"who":"Lecturer","line":"Now, the benefits. Some are what you'd expect: less flooding, because an open channel can spread out when the water rises. But others have surprised researchers. One is temperature. Running water and the plants beside it cool the air, and in hot weather the streets close to a daylighted stream can be several degrees cooler than streets just a few blocks away. That matters as summers get hotter."},{"who":"Lecturer","line":"Wildlife is another benefit. You might think it would take decades for anything to live in a stream that has been in the dark for a hundred years. In fact, fish and insects often return within a year or two, carried down from the stretches that were never buried. Birds follow soon after."},{"who":"Lecturer","line":"There's also an economic effect. Once a stream is open, the area around it tends to become much more attractive. Property values rise, and more cafés open along the banks, which brings people into streets they used to avoid. The best-known case is in Seoul, where a busy elevated road was removed in the early two-thousands and the stream beneath it opened up. It's now one of the most visited places in the city."},{"who":"Lecturer","line":"Finally, let's turn to the challenges, because daylighting is not always welcome. Cost is an issue, of course, although as I said, it may be cheaper in the long run. Space is another, since roads sometimes have to become narrower. But in most projects, the strongest opposition comes from local shopkeepers, who worry that losing parking spaces and lanes of traffic will keep customers away. Interestingly, studies of completed projects suggest that their trade usually improves once the work is finished, but persuading them of that in advance is not easy."},{"who":"Lecturer","line":"So, to sum up, buried streams were hidden for practical reasons in their time, but they now cost cities money and add to flooding. Opening them up is slow and sometimes controversial, but the results can make a city cooler, greener and more pleasant to live in. Next week we'll look at another kind of hidden infrastructure: the tunnels under our streets that carry power and data."}],"notes":{"title":"Daylighting: opening up buried city streams","headings":["History","Problems","The process","Benefits","Challenges"],"extra":["The process · a short stretch can take three or four years","Benefits · a well-known example: a stream opened up under a former elevated road"]},"groups":[{"instruction":"Questions 31-40. Complete the notes below. Write ONE WORD ONLY for each answer.","qtype":"note","questions":[{"n":31,"kind":"gap","prompt":"History · in the 19th century, streams were used to carry ___ away from houses and factories","accept":["waste"],"limit":1,"evidence":"They were used to carry waste away","why":{"en":"\"They were used to carry waste away from houses and factories.\"","tr":"\"Evlerden ve fabrikalardan atıkları taşımak için kullanıldılar.\"","fa":"«برای بردن فاضلاب و زباله از خانه‌ها و کارخانه‌ها استفاده می‌شدند»."},"trap":["TR-paraphrase"]},{"n":32,"kind":"gap","prompt":"History · streams were covered to make room for new ___ and railways","accept":["roads"],"limit":1,"evidence":"to make room for new roads and railways","why":{"en":"\"Railways\" is printed. Write roads, with the s.","tr":"\"Railways\" yazılı. roads’u s’siyle yaz.","fa":"«railways» چاپ شده. roads را با s بنویس."},"trap":["TR-plural"]},{"n":33,"kind":"gap","prompt":"Problems · heavy rain fills the pipes and causes ___","accept":["flooding"],"limit":1,"evidence":"The result is flooding","why":{"en":"\"When there’s very heavy rain... the result is flooding\" = causes flooding.","tr":"\"Çok şiddetli yağmur olduğunda... sonuç sel\" = sele yol açar.","fa":"«وقتی باران خیلی شدید است... نتیجه‌اش سیل است» یعنی سیل ایجاد می‌کند."},"trap":["TR-paraphrase"]},{"n":34,"kind":"gap","prompt":"Problems · repairing the old brick ___ is very expensive","accept":["tunnels"],"limit":1,"evidence":"those brick tunnels are now well over a century old","why":{"en":"\"Brick\" is printed, and you hear the plural: tunnels.","tr":"\"Brick\" yazılı ve çoğulunu duyuyorsun: tunnels.","fa":"«brick» چاپ شده و شکل جمع را می‌شنوی: tunnels."},"trap":["TR-plural"]},{"n":35,"kind":"gap","prompt":"The process · first, a survey using old ___ to find the route","accept":["maps"],"limit":1,"evidence":"a survey using old maps","why":{"en":"\"Engineers usually begin with a survey using old maps\", because modern plans often leave the streams out.","tr":"\"Mühendisler genelde eski haritalarla bir araştırmayla başlar\", çünkü modern planlarda dereler çoğu zaman yoktur.","fa":"«مهندس‌ها معمولاً با بررسیِ نقشه‌های قدیمی شروع می‌کنند»، چون نقشه‌های امروزی اغلب نهرها را نشان نمی‌دهند."},"trap":["TR-plural"]},{"n":36,"kind":"gap","prompt":"The process · the new channel is lined with ___, not concrete","accept":["gravel"],"limit":1,"evidence":"prefer to line it with gravel","why":{"en":"\"You might expect... concrete. In fact, designers now prefer to line it with gravel.\"","tr":"\"Beton bekleyebilirsiniz. Aslında tasarımcılar artık onu çakılla kaplamayı tercih ediyor.\"","fa":"«شاید انتظار بتن داشته باشی. در واقع طراح‌ها حالا ترجیح می‌دهند کفش را با شن بپوشانند»."},"trap":["TR-paraphrase"]},{"n":37,"kind":"gap","prompt":"Benefits · nearby streets can be several degrees ___ in hot weather","accept":["cooler"],"limit":1,"evidence":"several degrees cooler than streets just a few blocks away","why":{"en":"\"Several degrees cooler\": write the comparative form you hear.","tr":"\"Birkaç derece daha serin\": duyduğun karşılaştırma biçimini yaz.","fa":"«چند درجه خنک‌تر»: همان صفت تفضیلی را که می‌شنوی بنویس."},"trap":["TR-paraphrase"]},{"n":38,"kind":"gap","prompt":"Benefits · fish and ___ often return within a year or two","accept":["insects"],"limit":1,"evidence":"fish and insects often return within a year or two","why":{"en":"Not decades, as you might think: \"fish and insects often return within a year or two\". Plural.","tr":"Sanıldığı gibi on yıllar değil: \"balıklar ve böcekler çoğu zaman bir iki yıl içinde döner\". Çoğul.","fa":"نه چند دهه، آن‌طور که شاید فکر کنی: «ماهی‌ها و حشره‌ها اغلب ظرف یکی دو سال برمی‌گردند». جمع."},"trap":["TR-plural"]},{"n":39,"kind":"gap","prompt":"Benefits · property values rise and more ___ open along the banks","accept":["cafés","cafes"],"limit":1,"evidence":"more cafés open along the banks","why":{"en":"\"Property values rise, and more cafés open along the banks.\"","tr":"\"Mülk değerleri artar ve kıyı boyunca daha fazla kafe açılır.\"","fa":"«قیمت ملک بالا می‌رود و کافه‌های بیشتری کنار رود باز می‌شوند»."},"trap":["TR-plural"]},{"n":40,"kind":"gap","prompt":"Challenges · the strongest opposition usually comes from local ___","accept":["shopkeepers"],"limit":1,"evidence":"the strongest opposition comes from local shopkeepers","why":{"en":"Cost and space are issues, but \"the strongest opposition comes from local shopkeepers\". One word.","tr":"Maliyet ve alan sorun ama \"en güçlü muhalefet yerel esnaftan gelir\". Tek kelime.","fa":"هزینه و جا مسئله‌اند، اما «قوی‌ترین مخالفت از مغازه‌دارهای محلی است». یک کلمه."},"trap":["TR-limit","TR-plural"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Lecturer":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_isabella"},"role":"Lecturer"}},"sequence":[{"type":"announcer","text":"Part 4. You will hear a lecture about streams that were buried under cities. First, you have some time to look at Questions 31 to 40."},{"type":"pause","seconds":45,"note":"reading time, Questions 31-40"},{"type":"announcer","text":"Now listen carefully and answer Questions 31 to 40."},{"type":"sfx","note":"lecture-room acoustics: slight room reverb; 1.5 s between paragraphs"},{"type":"lines","from":0,"to":8},{"type":"announcer","text":"That is the end of Part 4. You now have two minutes to check your answers.","after":120}]},"id":"c-x05-l4-d","course":"ielts-exams","exam":"exam-05","unit":"x05-l4"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"In a lecture, \"daylighting a stream\" means...","options":["bringing a buried stream back to the surface","adding lights along a river","measuring how much sunlight a river gets"],"correct":0,"why":{"en":"Daylighting = opening up a stream that was hidden underground.","tr":"Daylighting = yer altına gizlenmiş bir dereyi açığa çıkarmak.","fa":"daylighting یعنی بیرون آوردن نهری که زیر زمین پنهان بوده."}},{"tests":"paraphrase","point":2,"prompt":"Note: \"Problem: costly to ___ old pipes\". Which words in a lecture would give the answer?","options":["the pipes were laid a long time ago","old pipes are hard to find","maintaining the old pipes takes a lot of money"],"correct":2,"why":{"en":"Costly = takes a lot of money; the verb in the gap is maintain.","tr":"Costly = çok paraya mal olur; boşluktaki fiil maintain.","fa":"costly یعنی پول زیادی می‌برد؛ فعل جای خالی maintain است."}},{"tests":"method","point":2,"prompt":"The lecturer says \"Finally, let’s turn to the challenges.\" Where are you in the notes?","options":["at the first heading","at the last heading","in the middle of the benefits"],"correct":1,"why":{"en":"\"Finally\" and the heading word \"challenges\" move you to the last part of the notes.","tr":"\"Finally\" ve başlık kelimesi \"challenges\" seni notların son kısmına götürür.","fa":"«Finally» و کلمه‌ی عنوان «challenges» تو را به بخش آخر یادداشت‌ها می‌برند."}},{"tests":"trap","point":3,"prompt":"Note: \"Plants on the banks attract ___ (ONE WORD ONLY)\". You hear: \"You might expect ducks, but actually it’s mainly butterflies.\" What do you write?","options":["butterflies","ducks","butterfly"],"correct":0,"why":{"en":"Ducks are the expected answer; \"actually\" gives the right one, in the plural you hear: butterflies.","tr":"Ördekler beklenen cevap; \"actually\" doğrusunu, duyduğun çoğul biçimiyle veriyor: butterflies.","fa":"اردک جواب قابل انتظار است؛ «actually» جواب درست را به همان شکل جمعی که می‌شنوی می‌دهد: butterflies."}},{"tests":"trap","point":1,"prompt":"Note: \"Main users: local ___ (ONE WORD ONLY)\". You hear: \"These days the path is mostly used by local residents walking their dogs.\" What do you write?","options":["local residents","residents walking","residents"],"correct":2,"why":{"en":"\"local\" is printed before the gap, so write one word: residents.","tr":"\"local\" boşluktan önce yazılı; tek kelime yaz: residents.","fa":"«local» قبل از جای خالی چاپ شده، پس یک کلمه بنویس: residents."}}],"id":"c-x05-l4-x","course":"ielts-exams","exam":"exam-05","unit":"x05-l4"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
